import Foundation
import Testing
@testable import MarblesPhysics

/// Cross-client check against ios/Fixtures/golden/geometry.json (generated by `npm run golden`).
struct GoldenGeometryTests {
    static func load() throws -> [[String: Any]] {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Fixtures/golden/geometry.json")
        let obj = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any]
        return obj?["cases"] as? [[String: Any]] ?? []
    }

    @Test func constantsMatchWeb() throws {
        let cases = try Self.load()
        func num(_ fn: String) -> Double? { cases.first { $0["fn"] as? String == fn }?["output"] as? Double }
        #expect(num("const:MARBLE_RADIUS") == JarGeometry.marbleRadius)
        #expect(num("const:JAR_WIDTH") == JarGeometry.width)
        #expect(num("const:JAR_HEIGHT") == JarGeometry.height)
        #expect(num("const:CELL_SIZE") == JarGeometry.cellSize)
    }

    @Test func marblePositionsMatchWeb() throws {
        let cases = try Self.load().filter { $0["fn"] as? String == "marblePosition" }
        #expect(cases.count == 24)
        for c in cases {
            let hour = try #require((c["input"] as? [String: Any])?["hour"] as? Int)
            let out = try #require(c["output"] as? [String: Any])
            let p = JarGeometry.marblePosition(hour: hour)
            #expect(p.x == out["cx"] as? Double && p.y == out["cy"] as? Double, "hour \(hour)")
        }
    }

    @Test func collidersMatchWeb() throws {
        let c = try #require(Self.load().first { $0["fn"] as? String == "const:JAR_COLLIDERS" })
        let segs = try #require(c["output"] as? [[String: Double]])
        #expect(segs.count == JarGeometry.colliders.count)
        for (want, got) in zip(segs, JarGeometry.colliders) {
            for (w, g) in [(want["x1"], got.x1), (want["y1"], got.y1), (want["x2"], got.x2), (want["y2"], got.y2)] {
                #expect(abs((w ?? .nan) - g) < 1e-9)
            }
        }
    }
}
